//! TPC-DS on a cluster: the same data and the same 24 `q` / `qSQL` queries as the single-node `tpc ds` example, run on
//! a cluster of shard nodes (in this process, talking Arrow Flight over TCP) and on one engine; the answers must agree.
//!
//!   (with `--config cluster.json` it connects to shard nodes that are already running)
//!   cargo run --release -p kix-control --example tpcds_cluster [-- --sf 0.05 --shards 3]
//!
//! The data is generated by the single-node example's generator into one engine, then copied through the control node
//! (so every row is routed by its shard key or replicated), then each query runs on both and the answers are compared.
//! The exit status is non-zero when an answer differs or a query fails.
#[path = "../../../../examples/tpc/ds.rs"]
mod ds;
#[path = "../../../../examples/tpc/util.rs"]
mod util;

use kix_control::Cluster;
use kix_shared_ces::{ClusterConfig, ShardInfo};
use kix_storage::{spawn, ShardNode};
use kixdb::sym::intern;
use kixdb::{Attr, ColVec, Interceptor, Server, K};
use std::sync::Arc;
use std::time::Instant;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let flag = |name: &str| args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).and_then(|v| v.parse::<f64>().ok());
    let sf = flag("--sf").unwrap_or(0.05);
    let nshards = flag("--shards").unwrap_or(3.0) as usize;

    println!("== TPC-DS on {nshards} shards (scale factor {sf}) ==");
    let single = Server::new();
    let mut oc = single.connect();
    let t = Instant::now();
    let data = ds::load(&mut oc, sf);
    println!("single node loaded in {:.2}s", t.elapsed().as_secs_f64());

    let rt = tokio::runtime::Runtime::new().unwrap();
    let mut shards = vec![];
    let cfg = match args.iter().position(|a| a == "--config").and_then(|i| args.get(i + 1)) {
        Some(path) => ClusterConfig::from_file(path).unwrap_or_else(|e| {
            eprintln!("{e}");
            std::process::exit(2)
        }),
        None => {
            for i in 0..nshards {
                shards.push(rt.block_on(spawn(ShardNode::new(i as u32, Server::new()), "127.0.0.1:0".parse().unwrap())).unwrap());
            }
            ClusterConfig { shards: shards.iter().enumerate().map(|(i, s)| ShardInfo { id: i as u32, addr: s.addr.to_string() }).collect() }
        }
    };
    let cluster = Cluster::connect(&cfg).unwrap();
    let mut cs = cluster.session();

    let t = Instant::now();
    for dist in ds::DISTRIBUTE {
        cs.eval(dist).unwrap_or_else(|e| panic!("{dist}: {e}"));
    }
    cs.eval(ds::SCHEMA).unwrap_or_else(|e| panic!("SCHEMA: {e}"));

    let mut copied = 0usize;
    for &table in ds::TABLES {
        let flip = match oc.get_var_direct(table).unwrap() {
            K::Table(t) => (*t).clone(),
            K::KeyedTable(kt) => kt.unkey(),
            _ => unreachable!(),
        };
        copied += flip.nrows();
        for start in (0..flip.nrows()).step_by(50_000) {
            let end = (start + 50_000).min(flip.nrows());
            let idx: Vec<usize> = (start..end).collect();
            let sub = K::Table(Arc::new(flip.gather(&idx)));
            let msg = K::Vector(ColVec::General(Attr::None, Arc::new(vec![K::Sym(intern("upsert")), K::Sym(intern(table)), sub])));
            if let Some(Err(e)) = cs.eval_message(&msg) {
                panic!("loading {table}: {e}");
            }
        }
    }
    println!("cluster loaded ({copied} rows copied through the control node) in {:.2}s", t.elapsed().as_secs_f64());

    let mut failures = 0;
    let (mut single_total, mut cluster_total) = (0.0, 0.0);
    println!("{:<40} {:>9} {:>9}  {:<34} answer", "query", "single", "cluster", "plan");
    for (name, q) in ds::queries() {
        if let Some(i) = args.iter().position(|a| a == "--only") {
            let wanted = args.get(i + 1).cloned().unwrap_or_default();
            if !wanted.split(',').any(|w| name.split_whitespace().next().is_some_and(|n| n.eq_ignore_ascii_case(w.trim()))) {
                continue;
            }
        }
        let (a, ta) = util::timed(&mut oc, &q);
        let t = Instant::now();
        let res = util::out_of(&cs.execute(&q));
        let tb = t.elapsed().as_secs_f64();
        let plan = cs
            .last_plan()
            .iter()
            .map(|p| p.split_whitespace().next().unwrap_or("").trim_end_matches(':').to_string())
            .collect::<Vec<_>>()
            .join(",");
        single_total += ta;
        cluster_total += tb;
        let verdict = match (&a, &res) {
            (Ok(expected), Ok(out)) => match util::compare_rows(&out.rows, expected) {
                None => match ds::check(&data, &name, &out.rows) {
                    Some(Ok(())) => "same (and checked against the generated rows)".to_string(),
                    Some(Err(e)) => {
                        failures += 1;
                        format!("WRONG against the generated rows: {e}")
                    }
                    None => "same".to_string(),
                },
                Some(diff) => {
                    failures += 1;
                    format!("DIFFERENT: {diff}")
                }
            },
            (Err(e), Err(ce)) if e == ce => "same error".to_string(),
            (Ok(_), Err(ce)) => {
                failures += 1;
                format!("CLUSTER ERROR: {ce}")
            }
            (Err(e), Ok(_)) => {
                failures += 1;
                format!("single node failed: {e}")
            }
            (Err(_), Err(_)) => "both fail".to_string(),
        };
        println!("{:<40} {:>8.3}s {:>8.3}s  {:<34} {}", name, ta, tb, plan, verdict);
        if std::env::var("PLAN_ALL").is_ok() || args.iter().any(|a| a == "--only") {
            for l in cs.last_plan() {
                println!("      plan: {l}");
            }
        }
    }
    println!("total: single {single_total:.2}s, cluster {cluster_total:.2}s, {failures} problem(s)");
    for s in shards {
        rt.block_on(s.shutdown());
    }
    std::process::exit(if failures == 0 { 0 } else { 1 });
}
